@if(isset($faqs) && $faqs->isNotEmpty())
<section class="faq-section"><div class="faq-container"><header class="faq-header"><h2 class="faq-title">{{ $service->name }} FAQ</h2><p class="faq-subtitle">Answers to common questions about {{ strtolower($service->name) }}.</p></header><div class="faq-list">@foreach($faqs as $faq)<article class="faq-item" onclick="toggleFaq(this)"><div class="faq-question"><span>{{ $faq->question }}</span><b>+</b></div><div class="faq-answer"><p>{{ $faq->answer }}</p></div></article>@endforeach</div></div></section>
<style>.faq-section{background:#fff;padding:64px 0}.faq-container{max-width:1050px;margin:auto;padding:0 24px}.faq-header{text-align:center;margin-bottom:32px}.faq-title{color:#0b2545;font:700 34px Arial;margin:0 0 10px}.faq-subtitle{font:16px Arial;color:#526b81;margin:0}.faq-list{display:grid;gap:12px}.faq-item{border:1px solid #d7e1e8;border-radius:12px;cursor:pointer;overflow:hidden}.faq-question{display:flex;align-items:center;justify-content:space-between;padding:20px 22px;color:#102b49;font:600 16px Arial}.faq-question b{background:#edf2f7;border-radius:50%;color:#52708c;display:grid;font-size:21px;height:28px;place-items:center;width:28px}.faq-answer{display:none;border-top:1px solid #d7e1e8;padding:17px 22px}.faq-answer p{color:#526b81;font:15px/1.65 Arial;margin:0}.faq-item.active{border-color:#0b2545}.faq-item.active .faq-question{background:#0b2545;color:#fff}.faq-item.active .faq-question b{background:transparent;color:#fff}.faq-item.active .faq-answer{display:block}@media(max-width:600px){.faq-section{padding:48px 0}.faq-title{font-size:27px}}</style><script>function toggleFaq(item){document.querySelectorAll('.faq-item').forEach(function(el){if(el!==item)el.classList.remove('active')});item.classList.toggle('active')}</script>
